def check() -> bool:
    for n in range(1, 6):
        vertices = list(range(n))
        possible_edges = list(itertools.combinations(vertices, 2))
        num_possible = len(possible_edges)
        for mask in range(1 << num_possible):
            edges = [possible_edges[i] for i in range(num_possible) if (mask & (1 << i))]
            adj = {v: [] for v in vertices}
            for u, v in edges:
                adj[u].append(v)
                adj[v].append(u)

            visited = set()
            stack = [0]
            while stack:
                curr = stack.pop()
                if curr not in visited:
                    visited.add(curr)
                    stack.extend(adj[curr])
            if len(visited) != n:
                continue

            vis = [False] * n
            def has_cycle(v, p):
                vis[v] = True
                for neighbor in adj[v]:
                    if neighbor == p:
                        continue
                    if vis[neighbor] or has_cycle(neighbor, v):
                        return True
                return False

            contains_cycle = has_cycle(0, -1)
            if (not contains_cycle) != (len(edges) == n - 1):
                return False
    return True

