            degrees = [0] * n
            for u, v in edges:
                degrees[u] += 1
                degrees[v] += 1
            max_deg = max(degrees) if degrees else 0
            k = max_deg + 1

            valid_coloring_exists = False
            for coloring in itertools.product(range(k), repeat=n):
                valid = True
                for u, v in edges:
                    if coloring[u] == coloring[v]:
                        valid = False
                        break
                if valid:
                    valid_coloring_exists = True
                    break
            if not valid_coloring_exists:
                return False
    return True

