def check() -> bool:
    def count_distinct(n, max_val):
        if n == 0: return 1
        if n < 0 or max_val <= 0: return 0
        return count_distinct(n - max_val, max_val - 1) + count_distinct(n, max_val - 1)

    def count_odd(n, max_val):
        if n == 0: return 1
        if n < 0 or max_val <= 0: return 0
        if max_val % 2 == 0:
            return count_odd(n, max_val - 1)
        return count_odd(n - max_val, max_val) + count_odd(n, max_val - 2)

    for n in range(1, 25):
        if count_distinct(n, n) != count_odd(n, n if n % 2 != 0 else n - 1):
            return False
    return True

