def check() -> bool:
    def is_prime(m):
        if m < 2:
            return False
        for i in range(2, int(math.isqrt(m)) + 1):
            if m % i == 0:
                return False
        return True

    for n in range(5, 101):
        if not is_prime(n):
            if math.factorial(n - 1) % n != 0:
                return False
    return True

