def check() -> bool:
    import itertools
    elements = (0, 1, 2, 3)
    pairs = list(itertools.product(elements, elements))
    for r_len in range(len(pairs) + 1):
        for R_tuples in itertools.combinations(pairs, r_len):
            R = set(R_tuples)
            reflexive = all((x, x) in R for x in elements)
            if not reflexive:
                continue
            transitive = all((x, z) in R for (x, y1) in R for (y2, z) in R if y1 == y2)
            if not transitive:
                continue
            symmetric = all((y, x) in R for (x, y) in R)
            is_equiv = reflexive and transitive and symmetric
            if is_equiv != symmetric:
                return False
    return True

