    A = (0, 1, 2)
    B = (0, 1, 2, 3)
    C = (0, 1, 2, 3)
    for f_tuple in itertools.product(B, repeat=len(A)):
        for g_tuple in itertools.product(C, repeat=len(B)):
            gf = [g_tuple[f_tuple[x]] for x in range(len(A))]
            gf_injective = len(set(gf)) == len(A)
            f_injective = len(set(f_tuple)) == len(A)
            if gf_injective and not f_injective:
                return False
    return True
